// marshalGooglechatconnectionsGoogleChatConnectionToGoogleChatConnectionResponseBody
// builds a value of type *GoogleChatConnectionResponseBody from a value of
// type *googlechatconnections.GoogleChatConnection.
func marshalGooglechatconnectionsGoogleChatConnectionToGoogleChatConnectionResponseBody(v *googlechatconnections.GoogleChatConnection) *GoogleChatConnectionResponseBody {
	res := &GoogleChatConnectionResponseBody{
		ID:         v.ID,
		Email:      v.Email,
		Status:     v.Status,
		Generation: v.Generation,
	}
	if v.GrantedScopes != nil {
		res.GrantedScopes = make([]string, len(v.GrantedScopes))
		for i, val := range v.GrantedScopes {
			res.GrantedScopes[i] = val
		}
	} else {
		res.GrantedScopes = []string{}
	}

	return res
}

